package approvals
import("crypto/sha256";"encoding/hex";"errors";"path/filepath";"testing")
func TestLexOpenStagedMetadataStoreDurableReceiptAndOneUse(t *testing.T){path:=filepath.Join(t.TempDir(),"approvals.json");s,e:=Open(path);if e!=nil{t.Fatal(e)};a:=Approval{Kitty:"kitty",Connector:"altazor-dropbox-0123456789abcdef",Kind:"dropbox",Action:"search",Args:map[string]any{"action":"search","query":".pdf","limit":"5"},Chat:"chat",RequestID:"request",RequestHash:"bound-metadata"};p,e:=s.RequestMetadataAction(a);if e!=nil{t.Fatal(e)};if _,e=s.Decide(p.ID,true,"",false);e==nil{t.Fatal("unready metadata executed")};p,e=s.ReadyMetadataAction(p.ID);if e!=nil||!p.MetadataStageReady||p.FileStageReady{t.Fatal("wrong readiness")};again,e:=Open(path);if e!=nil{t.Fatal(e)};p,e=again.Decide(p.ID,true,"",false);if e!=nil{t.Fatal(e)};raw:=`{"schema":"lexopen-cloud-metadata.v1","service":"dropbox","action":"search","items":[],"page_only":true,"exhaustive":false,"items_truncated":false}`;sum:=sha256.Sum256([]byte(raw));r:=&MetadataReceipt{State:"metadata_ready",RequestID:a.RequestID,ChatID:a.Chat,Kitty:a.Kitty,Connector:a.Connector,Kind:a.Kind,Action:a.Action,ApprovalID:p.ID,Target:map[string]any{"query":".pdf","limit":"5"},SHA256:hex.EncodeToString(sum[:]),Bytes:len(raw)};if e=again.DoneMetadataAction(p.ID,raw,"",r);e!=nil{t.Fatal(e)};third,e:=Open(path);if e!=nil{t.Fatal(e)};got,e:=third.Get(p.ID);if e!=nil||got.MetadataReceipt==nil||got.StructuredReceipt!=nil||got.MetadataReceipt.SHA256!=r.SHA256{t.Fatal("distinct receipt not durable")};if _,e=third.Decide(p.ID,true,"",false);e==nil{t.Fatal("durable approval replayed")};a.RequestHash="other-arguments";if _,e=third.RequestMetadataAction(a);!errors.Is(e,ErrFileActionConflict){t.Fatal("same request accepted changed binding")}}
func TestLexOpenStagedMetadataCannotBecomeFileReceipt(t *testing.T){s,e:=Open(filepath.Join(t.TempDir(),"approvals.json"));if e!=nil{t.Fatal(e)};_,e=s.RequestMetadataAction(Approval{Chat:"chat",RequestID:"r",RequestHash:"h",Kind:"dropbox",Action:"download_file"});if e==nil{t.Fatal("file action accepted as metadata")};a,e:=s.RequestFileAction(Approval{Chat:"chat",RequestID:"same",RequestHash:"file-domain",Kind:"dropbox",Action:"download_file"});if e!=nil{t.Fatal(e)};if _,e=s.ReadyMetadataAction(a.ID);e==nil{t.Fatal("file stage marked as metadata")};if _,e=s.RequestMetadataAction(Approval{Chat:"chat",RequestID:"same",RequestHash:"metadata-domain",Kind:"dropbox",Action:"list"});!errors.Is(e,ErrFileActionConflict){t.Fatal("file/metadata request collision")}}
